import { NextRequest, NextResponse } from "next/server"
import nodemailer from "nodemailer"
import { contactSchema } from "@/lib/contact-schema"

// Simple in-memory rate limiting: 1 request per 30 seconds per IP
const rateLimitMap = new Map<string, number>()
const RATE_LIMIT_WINDOW = 30_000 // 30 seconds

function isRateLimited(ip: string): boolean {
  const now = Date.now()
  const lastRequest = rateLimitMap.get(ip)

  if (lastRequest && now - lastRequest < RATE_LIMIT_WINDOW) {
    return true
  }

  rateLimitMap.set(ip, now)

  if (rateLimitMap.size > 100) {
    for (const [key, timestamp] of rateLimitMap.entries()) {
      if (now - timestamp > RATE_LIMIT_WINDOW) {
        rateLimitMap.delete(key)
      }
    }
  }

  return false
}

export async function POST(request: NextRequest) {
  try {
    const ip =
      request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
      request.headers.get("x-real-ip") ||
      "unknown"

    if (isRateLimited(ip)) {
      return NextResponse.json(
        { error: "Слишком много запросов. Подождите 30 секунд." },
        { status: 429 }
      )
    }

    const body = await request.json()
    const result = contactSchema.safeParse(body)

    if (!result.success) {
      const firstError = result.error.issues[0]
      return NextResponse.json(
        { error: firstError?.message || "Некорректные данные" },
        { status: 400 }
      )
    }

    const { name, phone, email, message } = result.data

    const smtpUser = process.env.SMTP_USER
    const smtpPass = process.env.SMTP_PASSWORD
    const notifyEmail = process.env.NOTIFY_EMAIL || smtpUser

    if (!smtpUser || !smtpPass) {
      console.error("SMTP credentials not configured")
      return NextResponse.json(
        { error: "Сервис временно недоступен. Позвоните нам по телефону." },
        { status: 500 }
      )
    }

    const transporter = nodemailer.createTransport({
      host: "smtp.yandex.ru",
      port: 465,
      secure: true,
      auth: {
        user: smtpUser,
        pass: smtpPass,
      },
    })

    const now = new Date().toLocaleString("ru-RU", { timeZone: "Europe/Moscow" })

    await transporter.sendMail({
      from: `"Timber Frame сайт" <${smtpUser}>`,
      to: notifyEmail,
      subject: `Новая заявка с сайта: ${name}`,
      html: `
        <h2>Новая заявка с timber-frame-spb.ru</h2>
        <table style="border-collapse:collapse;font-size:15px;">
          <tr><td style="padding:6px 12px;font-weight:bold;">Имя:</td><td style="padding:6px 12px;">${name}</td></tr>
          <tr><td style="padding:6px 12px;font-weight:bold;">Телефон:</td><td style="padding:6px 12px;"><a href="tel:${phone}">${phone}</a></td></tr>
          ${email ? `<tr><td style="padding:6px 12px;font-weight:bold;">Email:</td><td style="padding:6px 12px;"><a href="mailto:${email}">${email}</a></td></tr>` : ""}
          ${message ? `<tr><td style="padding:6px 12px;font-weight:bold;">Сообщение:</td><td style="padding:6px 12px;">${message}</td></tr>` : ""}
          <tr><td style="padding:6px 12px;font-weight:bold;">Время:</td><td style="padding:6px 12px;">${now}</td></tr>
          <tr><td style="padding:6px 12px;font-weight:bold;">IP:</td><td style="padding:6px 12px;">${ip}</td></tr>
        </table>
      `,
    })

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error("Contact form error:", error)
    return NextResponse.json(
      { error: "Произошла ошибка. Попробуйте позже." },
      { status: 500 }
    )
  }
}

